pub fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // If it's exactly 1x1, return the sole coefficient; otherwise return 0.0.
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

pub fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Validate input arrays.
    assert!(!x.is_empty(), "x must be non-empty");
    assert!(
        x.len() == y.len(),
        "x and y must have the same length"
    );

    // Validate coefficient grid.
    assert!(!c.is_empty(), "coefficient grid c must be non-empty");
    assert!(
        c.iter().all(|row| !row.is_empty()),
        "every row in coefficient grid c must be non-empty"
    );

    let n = x.len();
    let fill = default_value(&c);
    vec![fill; n]
}